#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step155-$TS"
echo "==> step155: portal accounts show real available quantity (#1)"
echo "    backup: $BK"
mkdir -p "$BK/routes" "$BK/lib"
cp "$GSZ/lib/nfPortal.js"      "$BK/lib/"    2>/dev/null || true
cp "$GSZ/routes/checkout.js"   "$BK/routes/" 2>/dev/null || true
cp "$GSZ/routes/products.js"   "$BK/routes/" 2>/dev/null || true

restore(){ echo "!! error — restoring"; cp "$BK/lib/nfPortal.js" "$GSZ/lib/" 2>/dev/null || true; cp "$BK/routes/checkout.js" "$GSZ/routes/" 2>/dev/null || true; cp "$BK/routes/products.js" "$GSZ/routes/" 2>/dev/null || true; }
trap 'restore' ERR

PATCHER=$(mktemp /tmp/patch_step155.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"

echo "==> applying"
NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"

echo "==> validating"
node --check "$GSZ/lib/nfPortal.js"
node --check "$GSZ/routes/checkout.js"
node --check "$GSZ/routes/products.js"
echo "    node --check ok (3 files)"

echo "==> restarting"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE after ${i}s"; false; }
echo "    homepage 200: OK (after ${i}s)"

rm -f "$PATCHER"
trap - ERR
echo ""
echo "==> step155 OK  Portal (full-account) plans now show the REAL free count from your Accounts Portal — e.g. '7 in stock' instead of just 'In stock' — on both the product page and checkout. If the portal is ever unreachable it quietly falls back to 'In stock' and never blocks a sale."
